begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create temporary table tap_results(line text);grant all on tap_results to authenticated;
create temporary table saved(name text primary key,data jsonb);grant all on saved to authenticated;
create function pg_temp.i(n integer) returns uuid language sql immutable as $$select ('93000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.ctx() returns jsonb language sql as $$select jsonb_build_object('organizationId',pg_temp.i(1),'branchId',pg_temp.i(101))$$;
create function pg_temp.login(n integer default 11) returns text language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.i(n),'session_id',pg_temp.i(n),'role','authenticated','is_anonymous',false)::text,true)$$;
create function pg_temp.source() returns jsonb language sql immutable as $$select '[{"sourceRow":2,"issuedOn":"2024-01-01","reference":"SI#01","name":"TEST Farmer","group":"CUSTOMER","amountCentavos":100000,"notes":"Original source note"},{"sourceRow":3,"issuedOn":"2023-01-01","reference":"SI#01","name":"TEST Farmer","group":"CUSTOMER","amountCentavos":50000},{"sourceRow":4,"issuedOn":"2024-01-01","reference":"BR-01","name":"TEST Branch","group":"BRANCH","amountCentavos":999999},{"sourceRow":5,"issuedOn":"2024-01-01","reference":"ZERO","name":"TEST Zero","group":"CUSTOMER","amountCentavos":0}]'::jsonb$$;
set local role authenticated;select pg_temp.login();
select public.agri_command('open_shift',pg_temp.ctx()||jsonb_build_object('deviceId',pg_temp.i(501),'openingCash',10000));
reset role;
rollback;
